import adalite

def get_domain_controllers():
    # 获取所有域控制器
    return adalite.get_all_dc()

def get_group_policies():
    # 获取所有组策略对象
    gpos = []
    for domain_controller in get_domain_controllers():
        gpos.extend(adalite.list_gpos(domain_controller))
    return gpos

def get_trust_relationships():
    # 获取域之间的信任关系
    return adalite.get trust_relations()

def main():
    try:
        # 连接到Active Directory
        ad = adalite.connect()

        print("Domain Controllers:")
        for dc in get_domain_controllers():
            print(dc)

        print("\nGroup Policies:")
        for gpo in get_group_policies():
            print(gpo)

        print("\nTrust Relationships:")
        for trust in get_trust_relationships():
            print(trust)

    except Exception as e:
        print(f"An error occurred: {e}")

if __name__ == "__main__":
